import { Outlet, NavLink, Navigate, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { useEffect, useRef, useState } from "react";
import api from "@/lib/api";
import {
  LayoutDashboard, ShoppingBag, Package, FolderOpen, BarChart3,
  Users, Cake, LogOut, Shield,
} from "lucide-react";

const NAV = [
  { to: "/admin", label: "Dashboard", icon: LayoutDashboard, end: true },
  { to: "/admin/orders", label: "Orders", icon: ShoppingBag },
  { to: "/admin/custom-cakes", label: "Custom Cakes", icon: Cake },
  { to: "/admin/products", label: "Products", icon: Package },
  { to: "/admin/categories", label: "Categories", icon: FolderOpen },
  { to: "/admin/customers", label: "Customers", icon: Users },
  { to: "/admin/reports", label: "Reports", icon: BarChart3 },
];

export default function AdminLayout() {
  const { user, loading, logout } = useAuth();
  const location = useLocation();
  const [unseenOrders, setUnseenOrders] = useState(0);
  const latestOrderIdsRef = useRef(new Set());
  const nav = useNavigate();

  if (loading) return <div className="min-h-screen flex items-center justify-center">Loading...</div>;
  if (!user || user.role !== "admin") return <Navigate to="/admin/login" replace />;

  const handleLogout = () => { logout(); nav("/admin/login"); };

  useEffect(() => {
    let isMounted = true;
    const pollOrders = async () => {
      try {
        const { data } = await api.get("/admin/orders");
        const incomingIds = data.map((o) => o.id);
        const unseen = incomingIds.filter((id) => !latestOrderIdsRef.current.has(id));

        if (isMounted) {
          if (location.pathname === "/admin/orders") {
            latestOrderIdsRef.current = new Set(incomingIds);
            setUnseenOrders(0);
          } else {
            if (latestOrderIdsRef.current.size === 0) {
              latestOrderIdsRef.current = new Set(incomingIds);
            } else if (unseen.length > 0) {
              setUnseenOrders((count) => count + unseen.length);
            }
          }
        }
      } catch (error) {
        console.error("Failed to poll admin orders", error);
      }
    };

    pollOrders();
    const interval = window.setInterval(pollOrders, 5000);
    return () => {
      isMounted = false;
      window.clearInterval(interval);
    };
  }, [location.pathname]);

  return (
    <div className="min-h-screen bg-[#FDFBF7] flex">
      <aside className="w-64 bg-[#3E2A1F] text-white flex flex-col shrink-0">
        <div className="p-5 border-b border-white/10">
          <div className="flex items-center gap-2">
            <Shield className="w-6 h-6 text-[#D97706]" />
            <div>
              <div className="font-display font-bold">SLV Admin</div>
              <div className="text-xs text-white/60">{user.username || user.email}</div>
            </div>
          </div>
        </div>
        <nav className="flex-1 p-3 space-y-1">
          {NAV.map(({ to, label, icon: Icon, end }) => {
            const isOrdersLink = to === "/admin/orders";
            return (
              <NavLink
                key={to}
                to={to}
                end={end}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm transition-colors ${isActive ? "bg-[#D97706] text-white" : "text-white/70 hover:bg-white/10 hover:text-white"}`
                }
              >
                <Icon className="w-4 h-4" />
                <span className="flex-1">{label}</span>
                {isOrdersLink && unseenOrders > 0 ? (
                  <span className="ml-auto inline-flex items-center justify-center min-w-[1.5rem] h-6 rounded-full bg-amber-100 text-amber-900 text-xs font-semibold">
                    {unseenOrders}
                  </span>
                ) : null}
              </NavLink>
            );
          })}
        </nav>
        <div className="p-3 border-t border-white/10">
          <button onClick={handleLogout} className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-white/70 hover:bg-white/10 w-full">
            <LogOut className="w-4 h-4" /> Logout
          </button>
        </div>
      </aside>
      <main className="flex-1 overflow-auto">
        <div className="p-6 lg:p-8 max-w-7xl mx-auto">
          <Outlet />
        </div>
      </main>
    </div>
  );
}
